-- See https://wiki.hypr.land/Configuring/Basics/Monitors/

-- Laptop panel, anchored at origin
hl.monitor({
    output   = "eDP-1",
    mode     = "preferred",   -- 1920x1080@60
    position = "0x0",
    scale    = 1,
})

-- Xiaomi ultrawide, to the right of the laptop.
-- Its EDID marks 3440x1440@30 as "preferred", which made everything feel
-- sluggish — pin 50Hz, the max this link offers at native res. (The panel
-- itself can do 100Hz+; getting there needs a higher-bandwidth cable/port.)
-- Matched by desc: so the rule survives moving to a different port/dock.
hl.monitor({
    output   = "desc:Xiaomi Corporation Mi monitor 5506010002216",
    mode     = "3440x1440@50",
    position = "1920x0",
    scale    = 1,
})

-- Acer X127H projector over HDMI — mirror the laptop panel.
-- Its EDID prefers 1024x768; pin 1080p to match eDP-1 so the mirror is 1:1.
-- Matched by desc: so extending stays the default for other HDMI displays.
hl.monitor({
    output = "desc:Acer Technologies Acer X127H JP3110015900",
    mode   = "1920x1080@60",
    scale  = 1,
    mirror = "eDP-1",
})

-- Fallback for anything else that gets plugged in
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = 1,
})


