-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
hl.on("hyprland.start", function ()
--   hl.exec_cmd(terminal)
  -- nm-applet removed: duplicated waybar's network module. Also masked in
  -- ~/.config/autostart/nm-applet.desktop, since uwsm starts XDG autostart
  -- entries and /etc/xdg/autostart/nm-applet.desktop would revive it.
  hl.exec_cmd("syncthing")
  -- Syncthing tray icon. Must be launched with the SYSTEM python: the script's
  -- shebang is "#!/usr/bin/env python3", which resolves to miniconda's
  -- interpreter here, and that has no PyGObject ("No module named 'gi'") — so
  -- plain `syncthing-gtk` silently dies on startup.
  -- Its config is set to autostart_daemon=0 / autokill_daemon=0 so it attaches
  -- to the daemon started above instead of spawning a second one (and killing
  -- the real one when the GUI exits).
  hl.exec_cmd("/usr/bin/python3 /usr/bin/syncthing-gtk --minimized")
  hl.exec_cmd("trayscale")
  -- GTK_THEME is a no-op here: cursor-clip is GTK4/libadwaita and GTK4
  -- dropped the old theme system. Its opacity comes from window_bg_color in
  -- ~/.config/gtk-4.0/gtk.css (pywal-generated), plus a blur layer rule.
  hl.exec_cmd("cursor-clip --daemon")
  hl.exec_cmd("swaync")                -- notification daemon, must be up before waybar's module subscribes
  hl.exec_cmd("waybar")
  hl.exec_cmd("awww-daemon")           -- wallpaper daemon (waypaper's backend)
  hl.exec_cmd("waypaper --restore")    -- reapply last wallpaper silently (no GUI)
  hl.exec_cmd("systemctl --user start hyprpolkitagent")
  hl.exec_cmd("hypridle")              -- auto-lock (10 min) + screen off (10.5 min)
  hl.exec_cmd("hyprlauncher -d --quiet") -- launcher daemon: instant opens
  -- Load hy3 (built manually against system headers; see memory note)
  hl.exec_cmd("hyprctl plugin load /home/oluwaseyi/.local/share/hy3/libhy3.so")
  hl.exec_cmd("hyprpm reload -n")      -- hyprpm-managed plugins (hyprglass)

end)

-- awww caches wallpapers per-output, so a monitor plugged in after startup
-- sits on a black fill — reapply the saved wallpaper whenever one appears.
hl.on("monitor.added", function ()
  hl.exec_cmd("waypaper --restore")
end)


