local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/Configuring/Basics/Binds/ for more
hl.bind(mainMod .. " + T", hl.dsp.exec_cmd(terminal))
local closeWindowBind = hl.bind(mainMod .. " + Q", hl.dsp.window.close())
-- closeWindowBind:set_enabled(false)
hl.bind(mainMod .. " + SHIFT + P", hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(terminal .. " -e " .. fileManager))
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("loginctl lock-session"))  -- lock screen (hyprlock via hypridle)
hl.bind(mainMod .. " + F", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(menu))
-- Project picker rather than a bare window: rofi list -> `code <path>`,
-- so there is no File>Open Folder step. Not the Project Manager
-- extension's own picker — its commands need an existing VS Code
-- window and its store is empty; this reads VS Code's own recents.
hl.bind(mainMod .. " + C", hl.dsp.exec_cmd("$HOME/.config/hypr/scripts/code-picker.sh"))
-- Quake-style drop-down terminal living in the scratchpad: first press
-- spawns it, later presses toggle visibility so the shell persists.
hl.bind(mainMod .. " + grave", hl.dsp.exec_cmd("$HOME/.config/waybar/scripts/scratch-term.sh"))
-- One-line learning capture -> the Syncthing-backed pool at
-- ~/ALIAS/learning (INBOX.md + daily/). Deliberately not inside a code
-- project: APF-C3/Notes is a Python package, not a note store.
hl.bind(mainMod .. " + N", hl.dsp.exec_cmd("$HOME/.config/waybar/scripts/learn-capture.sh"))
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())

if hl.plugin ~= nil and hl.plugin.hy3 ~= nil then
    ----------------------------------------------------
    -- hy3: i3-like manual tiling binds
    ----------------------------------------------------
    local hy3 = hl.plugin.hy3

    -- Move focus with mainMod + arrow keys (tree-aware)
    hl.bind(mainMod .. " + left",  hy3.move_focus("l"))
    hl.bind(mainMod .. " + right", hy3.move_focus("r"))
    hl.bind(mainMod .. " + up",    hy3.move_focus("u"))
    hl.bind(mainMod .. " + down",  hy3.move_focus("d"))

    -- Move windows with mainMod + SHIFT + arrow keys
    hl.bind(mainMod .. " + SHIFT + left",  hy3.move_window("l"))
    hl.bind(mainMod .. " + SHIFT + right", hy3.move_window("r"))
    hl.bind(mainMod .. " + SHIFT + up",    hy3.move_window("u"))
    hl.bind(mainMod .. " + SHIFT + down",  hy3.move_window("d"))

    -- i3-style splits: pick where the next window opens
    hl.bind(mainMod .. " + H", hy3.make_group("h", { ephemeral = true }))   -- split horizontal
    hl.bind(mainMod .. " + B", hy3.make_group("v", { ephemeral = true }))   -- split vertical ("below")
    hl.bind(mainMod .. " + W", hy3.make_group("tab", { toggle = true }))    -- i3 tabbed container
    hl.bind(mainMod .. " + J", hy3.change_group("opposite"))                -- flip split direction

    -- Focus parent / child container (i3's "focus parent")
    hl.bind(mainMod .. " + A",         hy3.change_focus("raise"))
    hl.bind(mainMod .. " + SHIFT + A", hy3.change_focus("lower"))

    -- Cycle tabs in a tabbed group
    hl.bind(mainMod .. " + bracketleft",  hy3.focus_tab({ direction = "l", wrap = true }))
    hl.bind(mainMod .. " + bracketright", hy3.focus_tab({ direction = "r", wrap = true }))

    -- Kill the whole selected node (window or entire group)
    hl.bind(mainMod .. " + SHIFT + Q", hy3.kill_active())
else
    ----------------------------------------------------
    -- Fallback: stock dwindle binds (hy3 not loaded)
    ----------------------------------------------------
    hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))    -- dwindle only

    -- Move focus with mainMod + arrow keys
    hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
    hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
    hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
    hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

    -- Move windows with mainMod + SHIFT + arrow keys
    hl.bind(mainMod .. " + SHIFT + left",  hl.dsp.window.move({ direction = "left" }))
    hl.bind(mainMod .. " + SHIFT + right", hl.dsp.window.move({ direction = "right" }))
    hl.bind(mainMod .. " + SHIFT + up",    hl.dsp.window.move({ direction = "up" }))
    hl.bind(mainMod .. " + SHIFT + down",  hl.dsp.window.move({ direction = "down" }))
end

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i, follow = false }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
