-- ── HyprGlass — Liquid Glass on shell surfaces ───────────────
if hl.plugin ~= nil and hl.plugin.hyprglass ~= nil then
    local hg = hl.plugin.hyprglass

    hg.config({
        default_theme = "dark",
        layers = { enabled = true },
    })

    -- whitelist: only these layers get glassed (the wallpaper layer stays untouched)
    hg.layer("waybar",       { preset = "subtle", mask_threshold = 0.05 })
    hg.layer("swaync-control-center",      { mask_threshold = 0.05 })
    hg.layer("swaync-notification-window", { mask_threshold = 0.05 })
    hg.layer("hyprlauncher", { preset = "subtle" })
    hg.layer("rofi",         { preset = "subtle" })

    -- keep video and fullscreen windows clean
    hl.window_rule({ name = "hyprglass-off-media",      match = { class = "^(mpv|vlc)$" }, tag = "+hyprglass_disabled" })
    hl.window_rule({ name = "hyprglass-off-fullscreen", match = { fullscreen = true },     tag = "+hyprglass_disabled" })
else
    -- fallback: plain frosted blur when hyprglass isn't loaded
    hl.layer_rule({ match = { namespace = "^hyprlauncher$" }, blur = true, ignore_alpha = 0.2 })
    hl.layer_rule({ match = { namespace = "^rofi$" },         blur = true, ignore_alpha = 0.2 })
    hl.layer_rule({ match = { namespace = "^waybar$" },       blur = true, ignore_alpha = 0.2 })
    -- swaync was missing here, so notification cards rendered flat against
    -- whatever was behind them instead of frosted like everything else.
    hl.layer_rule({ match = { namespace = "^swaync-notification-window$" }, blur = true, ignore_alpha = 0.2 })
    hl.layer_rule({ match = { namespace = "^swaync-control-center$" },      blur = true, ignore_alpha = 0.2 })
    -- cursor-clip's overlay is translucent by design and had no blur, so the
    -- wallpaper showed through raw and the entries were unreadable. Note the
    -- anchored "$": cursor-clip ALSO puts up a fullscreen "cursor-clip-capture"
    -- input layer, and blurring that would blur the entire screen.
    hl.layer_rule({ match = { namespace = "^cursor-clip$" }, blur = true, ignore_alpha = 0.0 })
end

-- Ghostty handles its own glass (background-opacity in its config) with
-- text staying solid — keep the compositor from fading it on top of that.
hl.window_rule({
    name  = "ghostty-solid-text",
    match = { class = "^(com\\.mitchellh\\.ghostty|ghostty)$" },
    opacity = "1.0 override 1.0 override",
})

-- VSCode glass, done at the compositor instead of by the vscode-vibrancy
-- extension. Vibrancy bought *solid text* by patching Electron's main.js in
-- /usr/share/code as root, which meant a pkexec prompt on every VSCode and
-- extension update. Not worth it. Electron has no background-opacity knob of
-- its own (unlike Ghostty above), so the whole window fades a little here,
-- text included. Global blur (decoration.blur) fills in behind it.
hl.window_rule({
    name  = "code-glass",
    match = { class = "^([Cc]ode|code-url-handler|code-oss|[Vv][Ss][Cc]odium)$" },
    opacity = "0.92 override 0.88 override",
})

-- ── Popups & dialogs should float, not tile ──────────────────

-- Any modal dialog ("Are you sure", auth prompts, etc.)
hl.window_rule({
    name  = "float-modals",
    match = { modal = true },
    float = true,
})

-- Thunar operation dialogs (file transfer progress, replace confirms, ...)
hl.window_rule({
    name  = "float-thunar-dialogs",
    match = {
        class = "^([Tt]hunar)$",
        title = "^(File Operation Progress|Confirm to replace files|Rename .*|Create New Folder|Attention|Compressing .*|Extracting .*)$",
    },
    float = true,
})

-- Chrome/Chromium popup windows (OAuth sign-in etc. open as about:blank)
hl.window_rule({
    name  = "float-chrome-popups",
    match = {
        class         = "^([Gg]oogle-chrome|[Cc]hromium|[Bb]rave-browser)$",
        initial_title = "^(about:blank)$",
    },
    float = true,
})

-- Generic auth / sign-in windows by title
hl.window_rule({
    name  = "float-auth-popups",
    match = { title = "^(Sign [Ii]n|Log [Ii]n|Login|Authentication [Rr]equired|Confirm).*" },
    float = true,
})

-- ── 🗄️ Scratchpad terminal ───────────────────────────────────
-- Anything tagged with this app-id lands in special:magic instead of the
-- tiling layout. ghostty --class sets it; scripts/scratch-term.sh spawns it.
hl.window_rule({
    name  = "scratch-term-to-special",
    match = { class = "^(com\\.scratch\\.term)$" },
    workspace = "special:magic",
})

-- ── 🐉 Garuda tools ──────────────────────────────────────────
-- Distro settings/maintenance GUIs. These are one-off dialogs you open,
-- change a thing in, and close — tiling them shoves the actual workspace
-- around for no benefit. Class confirmed at runtime as
-- "garuda-system-maintenance"; none of these ship a StartupWMClass, so the
-- pattern covers the binary names (incl. the two without a garuda- prefix).
hl.window_rule({
    name  = "float-garuda-tools",
    match = { class = "^([Gg]aruda-.*|setup-assistant|snapper-tools)$" },
    float  = true,
    center = true,
})

-- Portal file pickers (Open/Save dialogs)
hl.window_rule({
    name  = "float-file-pickers",
    match = { class = "^(xdg-desktop-portal-gtk|xdg-desktop-portal-kde|org.freedesktop.impl.portal.desktop.kde)$" },
    float = true,
})

-- ── 🖥️ Screen sharing ────────────────────────────────────────
-- The portal's source picker had NO rule at all, so it tiled into the layout
-- the moment a call asked to share — the worst possible time to be fighting
-- the window manager. Float it, centre it, and pin it above the tiles.
hl.window_rule({
    name  = "float-share-picker",
    match = { class = "^(hyprland-share-picker|xdg-desktop-portal-hyprland)$" },
    float  = true,
    center = true,
    pin    = true,
    size   = "720 480",
})

-- Chrome's "<site> is sharing your screen" indicator bar. Floats and pins so
-- it stops stealing a tile slot mid-call.
hl.window_rule({
    name  = "float-share-indicator",
    match = { title = ".*(is sharing your screen|Share your screen|Stop sharing).*" },
    float = true,
    pin   = true,
})

-- ── 🔐 Browser popups ────────────────────────────────────────
-- Chrome opens OAuth/sign-in flows via window.open. The old rule only caught
-- an initial title of exactly "about:blank"; in practice these map with an
-- empty title, so they slipped through and tiled.
hl.window_rule({
    name  = "float-chrome-popup-blank",
    match = {
        class         = "^([Gg]oogle-chrome|[Cc]hromium|[Bb]rave-browser|[Hh]elium)$",
        initial_title = "^(|about:blank|Sign in.*|.*Google Accounts.*)$",
    },
    float = true,
})

-- Auth flows by title, matched on the initial title so the rule fires at map
-- time rather than after the page has already been slotted into the layout.
hl.window_rule({
    name  = "float-auth-popups-initial",
    match = { initial_title = "^(Sign [Ii]n|Sign [Uu]p|Log [Ii]n|Login|Authentication [Rr]equired|Authorize|OAuth|Confirm|.*Google Accounts).*" },
    float = true,
})


hl.bind("SUPER + tab", function ()
    local layouts     = { "scrolling", "dwindle", "master", "monocle" }
    if hl.plugin ~= nil and hl.plugin.hy3 ~= nil then
        table.insert(layouts, 1, "hy3")
    end
    local workspace   = hl.get_active_workspace()
	if hl.get_active_special_workspace() then
		workspace = hl.get_active_special_workspace()
	end

    local next_layout = "dwindle"

    if not workspace then
        return
    end

    for i = 1, #layouts do
        if layouts[i] == workspace.tiled_layout then
            local next_layout_idx = (i % #layouts) + 1
            next_layout = layouts[next_layout_idx]
            break
        end
    end

	if workspace.special then
		hl.workspace_rule({ workspace = tostring(workspace.name), layout = next_layout })
	else
		hl.workspace_rule({ workspace = tostring(workspace.id), layout = next_layout })
	end
end)

hl.bind("SUPER + F1", function ()
    local game_mode = (hl.get_config("animations.enabled") == false)

    if game_mode then
        hl.exec_cmd("hyprctl reload")
        return
    end
    
    hl.config({
        general = {
            gaps_in = 0, gaps_out = 0, -- Disable gaps  
            border_size = 0,
        },

        animations = {
            enabled = false, -- Disable animations
        },
        
        -- Disable blur, shadow and window rounding
        decoration = {
            shadow = { enabled = false },
            blur = { enabled = false },
            rounding = 0,
        }
    })
end)
